import java.io.*;
import java.util.*;

public final class CF_630_D2_E_V5 {

    private static final boolean DEBUG = false;
    private static PrintWriter out;
    private static Scanner scanner;

    private static void debug(Object... args) {
        if (DEBUG) {
            for (Object o : args) System.err.print(o + " ");
            System.err.println();
        }
    }

    private static long modPow(long base, long exp, long mod) {
        base %= mod;
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    private static void run() throws IOException {
        out = new PrintWriter(System.out);
        scanner = new Scanner(System.in);

        long n = scanner.nextLong();
        long m = scanner.nextLong();
        int L = scanner.nextInt();
        int R = scanner.nextInt();

        long MOD = 998244353L;
        long total = n * m;
        long inv2 = modPow(2, MOD - 2, MOD);

        long diff = R - L + 1;
        long odd = diff / 2;
        long even = diff - odd;

        long ans;
        if (total % 2 == 1) {
            ans = modPow(diff, total, MOD);
        } else {
            long term1 = modPow(diff, total, MOD);
            long term2 = modPow(Math.abs(even - odd), total, MOD);
            ans = (term1 + term2) % MOD;
            ans = (ans * inv2) % MOD;
        }

        out.println(ans);
        out.close();
    }

    public static void main(String[] args) throws IOException {
        run();
    }

    static class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        Scanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        private void eat() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new IOException();
                st = new StringTokenizer(line);
            }
        }

        public int nextInt() throws IOException {
            eat();
            return Integer.parseInt(st.nextToken());
        }

        public long nextLong() throws IOException {
            eat();
            return Long.parseLong(st.nextToken());
        }
    }
}
